const crypto = require('crypto');
const raw = $input.first().json.brief_json;
if (typeof raw !== 'string' || Buffer.byteLength(raw, 'utf8') > 65536) throw new Error('invalid_brief_size');
const brief = JSON.parse(raw);
if (!brief || Array.isArray(brief) || typeof brief !== 'object') throw new Error('invalid_brief');
const secret = String($env.DROP_RATE_AUTOMATION_COMMAND_SECRET || '').trim();
const receiptUrl = String($env.DROP_RATE_API_AUTOMATION_CONTROL_URL || '').trim();
if (secret.length < 32) throw new Error('automation_command_secret_not_configured');
if (!/\/automation\/control\/receipt$/.test(receiptUrl)) throw new Error('automation_control_receipt_url_invalid');
const body = JSON.stringify(brief);
const timestamp = String(Math.floor(Date.now()/1000));
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body, 'utf8').digest('hex');
return [{json:{command_url:receiptUrl.replace(/\/automation\/control\/receipt$/, '/automation/commands/editorial/prepare'),command_body:body,command_timestamp:timestamp,command_signature:signature}}];

const response = $json;
const body = typeof response.body === 'string' ? JSON.parse(response.body) : response.body;
if (response.statusCode !== 200 || !body || body.schema_version !== 1 || body.publishable !== false || body.stored !== false) throw new Error('editorial_preparation_contract_failed');
if (!['PREPARED_FOR_REVIEW', 'NEEDS_EVIDENCE'].includes(body.status) || !Array.isArray(body.publication_blockers) || body.publication_blockers.length === 0) throw new Error('editorial_preparation_gate_missing');
return [{json:body}];
